import type { SVGProps } from "react";

export const ENTRY_LOGO_DATA_URI =
  "data:image/jpeg;base64,";

/** The official Entry logo symbol (liquid infinity mark). */
export function EntryMark({
  className,
  style,
  ...props
}: SVGProps<SVGSVGElement>) {
  return (
    <svg
      aria-hidden="true"
      className={className}
      style={style}
      viewBox="0 0 1024 983"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      {...props}
    >
      <image
        href={ENTRY_LOGO_DATA_URI}
        width="1024"
        height="983"
        preserveAspectRatio="xMidYMid meet"
      />
    </svg>
  );
}
